import Foundation

/// Decides whether a pasteboard change may leave the Mac.
public enum ClipboardPolicy {
    /// Markers defined by nspasteboard.org and set by password managers and similar apps.
    public static let secretMarkers: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]

    public static func shouldSync(types: [String], text: String?) -> Bool {
        guard let text, !text.isEmpty, text.utf8.count <= RohyProtocol.maxTextBytes else { return false }
        return secretMarkers.isDisjoint(with: types)
    }
}

/// Remembers the pasteboard state written by Rohy itself, so it is not sent back (no echo loop).
public struct EchoGuard {
    private var ownChangeCount: Int?
    private var lastSeenChangeCount: Int?

    /// Pass the change count observed at startup so existing content is not sent.
    public init(currentChangeCount: Int? = nil) {
        lastSeenChangeCount = currentChangeCount
    }

    /// Call right after Rohy wrote to the pasteboard, with the resulting change count.
    public mutating func markWritten(changeCount: Int) {
        ownChangeCount = changeCount
        lastSeenChangeCount = changeCount
    }

    /// Returns true when the change count moved because of another app.
    public mutating func isExternalChange(changeCount: Int) -> Bool {
        defer { lastSeenChangeCount = changeCount }
        guard changeCount != lastSeenChangeCount else { return false }
        return changeCount != ownChangeCount
    }
}
